t.script:
(function(){
  var f = document.getElementById('dmn_reg_form');
  var box = document.getElementById('dmn_reg_alert');
  f.addEventListener('submit', function(e){
    e.preventDefault();
    var p = {token: f.token.value, name: f.name.value, email: f.email.value, phone: f.phone.value};
    fetch('/dmn/claim', {method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({jsonrpc:'2.0', method:'call', params:p, id:1})})
    .then(function(r){return r.json();})
    .then(function(d){
      var res = d.result || {};
      if(res.ok){
        var g = res.warranty_until ? (' Garantia hasta ' + res.warranty_until + '.') : '';
        box.innerHTML = '<div class="alert alert-success">Listo, ' + res.partner + '. Tu joya quedo registrada a tu nombre.' + g + '</div>';
        f.style.display = 'none';
        setTimeout(function(){ window.location.href='/visor'; }, 2500);
      } else {
        box.innerHTML = '<div class="alert alert-danger">' + (res.error || 'No se pudo registrar.') + '</div>';
      }
    })
    .catch(function(){ box.innerHTML = '<div class="alert alert-danger">Error de conexion.</div>'; });
  });
})();

xpath.script:
(function(){
  fetch('/dmn/dedication', {method:'POST', headers:{'Content-Type':'application/json'},
    body: JSON.stringify({jsonrpc:'2.0', method:'call', params:{}, id:1})})
  .then(function(r){return r.json();})
  .then(function(d){
    var res = d.result || {};
    if(!res.visible){return;}
    document.getElementById('dmn_ded_text').textContent = res.text || '';
    document.getElementById('dmn_ded_from').textContent = res.from ? ('- ' + res.from) : '';
    if(res.image){ var im = document.getElementById('dmn_ded_img'); im.src = res.image; im.style.display='block'; }
    document.getElementById('dmn_dedication_block').style.display = 'flex';
  }).catch(function(){});
})();
